## Audit + tenant interceptor (BuildingBlocks)

```csharp
public sealed class AuditAndTenantInterceptor(
    ICurrentUserService currentUser,
    ITenantContext tenantContext,
    TimeProvider clock) : SaveChangesInterceptor
{
    public override InterceptionResult<int> SavingChanges(
        DbContextEventData eventData, InterceptionResult<int> result)
    {
        Stamp(eventData.Context);
        return result;
    }

    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData eventData, InterceptionResult<int> result, CancellationToken ct = default)
    {
        Stamp(eventData.Context);
        return ValueTask.FromResult(result);
    }

    private void Stamp(DbContext? context)
    {
        if (context is null) return;
        var now = clock.GetUtcNow();

        foreach (var entry in context.ChangeTracker.Entries())
        {
            if (entry.Entity is IAuditableEntity auditable)
            {
                if (entry.State == EntityState.Added)
                {
                    auditable.CreatedAt = now;
                    auditable.CreatedBy = currentUser.UserId;
                }
                if (entry.State is EntityState.Added or EntityState.Modified)
                {
                    auditable.ModifiedAt = now;
                    auditable.ModifiedBy = currentUser.UserId;
                }
            }

            if (entry.Entity is ITenantEntity tenantEntity)
            {
                if (entry.State == EntityState.Added)
                {
                    if (tenantContext.TenantId == default) // Guid.Empty / null for string
                        throw new InvalidOperationException(
                            "Cannot insert a tenant-scoped entity without a tenant context.");

                    tenantEntity.TenantId = tenantContext.TenantId;
                }
                else if (entry.State == EntityState.Modified
                         && entry.Property(nameof(ITenantEntity.TenantId)).IsModified)
                    throw new DomainException("Cannot change the TenantId of an existing entity.");
            }
        }
    }
}
```

Registration: `AddSingleton<TimeProvider>(TimeProvider.System)` and the interceptor as `Scoped`; in each module, `options.AddInterceptors(sp.GetRequiredService<AuditAndTenantInterceptor>())`. If the module collects domain events/Outbox in `SaveChanges`, do it in a sibling interceptor in the same `SavingChanges`.

